import React, { useEffect, useState } from 'react';
import { AnswerFeedback, Citation, FeedbackRating, QAHistory, QAResponse } from '../../shared/types';

interface Props {
  history: QAHistory[];
  onClear: () => void;
}

/**
 * Full Q&A history rendered as a conversation: each question as a user
