  const [feedbackError, setFeedbackError] = useState<string | null>(null);

  // Reload stored ratings whenever the conversation changes or is reset.
  useEffect(() => {
    let cancelled = false;
    window.knowledgeBase.feedback
      .list()
      .then((entries: AnswerFeedback[]) => {
        if (cancelled) return;
        setRatings(Object.fromEntries(entries.map(e => [e.answerId, e.rating])));
