      setFeedbackError('Could not save feedback. Please try again.');
    }
  };

  if (history.length === 0) {
    return (
      <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
        No conversation yet. Ask a question to get started.
      </div>
    );
  }

  return (
    <div>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '16px',
      }}>
        <h3 style={{ fontSize: '16px', fontWeight: 600 }}>Conversation</h3>
        <button
          onClick={onClear}
          style={{
            padding: '4px 10px',
            background: '#d9534f',
            color: '#fff',
            border: 'none',
            borderRadius: '3px',
            cursor: 'pointer',
            fontSize: '12px',
          }}
        >
          Clear History
        </button>
      </div>

