      <div style={{ fontSize: '13px', lineHeight: 1.6, wordBreak: 'break-word' }}>
        {response.answer}
      </div>

      {/* Confidence indicator */}
      <div
        style={{ marginTop: '10px', display: 'flex', alignItems: 'center', gap: '8px', fontSize: '11px', color: '#8888bb' }}
