      {response.citations.length > 0 && (
        <div style={{ marginTop: '10px' }}>
          <div style={{ fontSize: '11px', color: '#8888bb', marginBottom: '4px' }}>
            Citations ({response.citations.length})
          </div>
          {response.citations.map((citation, i) => (
            <CitationItem key={`${citation.documentId}-${citation.chunkIndex}-${i}`} citation={citation} />
          ))}
        </div>
      )}

      {/* Feedback */}
      <div style={{ marginTop: '10px', display: 'flex', gap: '6px' }}>
        <FeedbackButton
          label="Mark answer helpful"
          text="Helpful"
          active={rating === 'up'}
          onClick={() => onRate('up')}
        />
        <FeedbackButton
          label="Mark answer not helpful"
          text="Not helpful"
          active={rating === 'down'}
          onClick={() => onRate('down')}
        />
      </div>

      <div style={{ marginTop: '6px', fontSize: '10px', color: '#555' }}>
        {new Date(response.timestamp).toLocaleString()}
      </div>
    </div>
  );
}

function CitationItem({ citation }: { citation: Citation }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <div style={{
      marginTop: '4px',
      paddingLeft: '8px',
      borderLeft: '2px solid #533483',
      fontSize: '12px',
      color: '#b0b0d0',
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
        <span style={{ minWidth: 0, wordBreak: 'break-word' }}>
          {citation.documentTitle} (chunk {citation.chunkIndex})
        </span>
        <button
          type="button"
          aria-expanded={expanded}
          onClick={() => setExpanded(!expanded)}
          style={{
            padding: '2px 6px',
            background: 'transparent',
            color: '#b088f9',
            border: '1px solid #533483',
            borderRadius: '3px',
            cursor: 'pointer',
            fontSize: '11px',
          }}
        >
          {expanded ? 'Hide excerpt' : 'Show excerpt'}
        </button>
      </div>
      {expanded && (
        <blockquote style={{
          marginTop: '4px',
          padding: '6px 8px',
          background: '#12122a',
          borderRadius: '3px',
          fontSize: '12px',
          lineHeight: 1.5,
          whiteSpace: 'pre-wrap',
          wordBreak: 'break-word',
        }}>
          {citation.excerpt}
        </blockquote>
      )}
    </div>
  );
}

function FeedbackButton({
  label,
  text,
  active,
  onClick,
}: {
  label: string;
  text: string;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      aria-pressed={active}
      onClick={onClick}
      style={{
        padding: '3px 10px',
        background: active ? '#533483' : 'transparent',
        color: active ? '#fff' : '#b0b0d0',
        border: '1px solid #533483',
        borderRadius: '12px',
        cursor: 'pointer',
        fontSize: '11px',
      }}
    >
      {text}
    </button>
  );
}

