import React, { useEffect, useRef, useState } from 'react';
import { QAHistory } from '../../shared/types';
import { ConversationHistory } from './ConversationHistory';

interface Props {
  history: QAHistory[];
  onAsk: (question: string) => Promise<void>;
  onClearHistory: () => void;
}

/** Question panel: the conversation so far, with the question input below it. */
export function QuestionPanel({ history, onAsk, onClearHistory }: Props) {
  const [question, setQuestion] = useState('');
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Keep the newest exchange in view.
  useEffect(() => {
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [history.length]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = question.trim();
    if (!trimmed || pending) return;

    setPending(true);
    setError(null);
    try {
      await onAsk(trimmed);
      setQuestion('');
    } catch (err) {
      console.error('Q&A failed:', err);
      setError('The question could not be answered. Please try again.');
    } finally {
      setPending(false);
    }
  };

  return (
    <div style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', background: '#1a1a2e' }}>
      <div
        ref={scrollRef}
        style={{ flex: 1, minHeight: 0, overflow: 'auto', padding: '20px' }}
      >
        <ConversationHistory history={history} onClear={onClearHistory} />
        {pending && (
          <div style={{ fontSize: '12px', color: '#888', marginTop: '8px' }}>Thinking...</div>
        )}
      </div>

      {error && (
        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: '#d9534f', background: '#16213e' }}>
          {error}
        </div>
      )}

      <form
        onSubmit={handleSubmit}
        style={{
          display: 'flex',
          padding: '12px 20px',
          borderTop: '1px solid #0f3460',
          background: '#16213e',
        }}
      >
        <input
          type="text"
          value={question}
          onChange={e => setQuestion(e.target.value)}
          placeholder="Ask a question about your documents..."
          aria-label="Question"
          style={{
            flex: 1,
            minWidth: 0,
            padding: '10px 14px',
            background: '#1a1a2e',
            color: '#e0e0e0',
            border: '1px solid #0f3460',
            borderRadius: '6px',
            fontSize: '14px',
            outline: 'none',
          }}
        />
        <button
          type="submit"
          disabled={pending}
          style={{
            marginLeft: '10px',
            padding: '10px 20px',
            background: '#533483',
            color: '#fff',
            border: 'none',
            borderRadius: '6px',
            cursor: pending ? 'default' : 'pointer',
            fontSize: '14px',
            fontWeight: 500,
            opacity: pending ? 0.6 : 1,
          }}
        >
          Ask
        </button>
      </form>
    </div>
  );
}

