import React, { useState, useCallback, useEffect } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { StatusBar } from './components/StatusBar';
import { Document, AppStatus, QAHistory } from '../shared/types';

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [confirmingReset, setConfirmingReset] = useState(false);
  const [resetError, setResetError] = useState<string | null>(null);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus(status);
    } catch (err) {
      console.error('Failed to refresh documents:', err);
    }
  }, []);

  const refreshHistory = useCallback(async () => {
    try {
      setHistory(await window.knowledgeBase.qa.history());
    } catch (err) {
      console.error('Failed to load conversation:', err);
    }
  }, []);

  useEffect(() => {
    refreshDocuments();
    refreshHistory();
  }, [refreshDocuments, refreshHistory]);

  const handleImport = useCallback(async () => {
    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
  }, []);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    await window.knowledgeBase.qa.ask(question);
    await refreshHistory();
    const status = await window.knowledgeBase.indexing.status();
    setAppStatus(status);
  }, [refreshHistory]);

  const handleClearHistory = useCallback(async () => {
    try {
      await window.knowledgeBase.qa.clearHistory();
      setHistory([]);
    } catch (err) {
      console.error('Failed to clear history:', err);
    }
  }, []);

  const handleConfirmReset = useCallback(async () => {
    try {
      await window.knowledgeBase.app.reset();
      setSelectedDoc(null);
      setConfirmingReset(false);
      setResetError(null);
      setHistory([]);
      await refreshDocuments();
    } catch (err) {
      console.error('Reset failed:', err);
      setResetError('Reset failed. Your data was not changed.');
    }
  }, [refreshDocuments]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button
            onClick={refreshDocuments}
            style={{
              padding: '6px 14px',
              background: '#0f3460',
              color: '#e0e0e0',
              border: '1px solid #1a1a4e',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '13px',
            }}
          >
            Refresh
          </button>
          <button
            aria-label="Reset all data"
            onClick={() => {
              setResetError(null);
              setConfirmingReset(true);
            }}
            style={{
              padding: '6px 14px',
              background: '#8b2f2c',
              color: '#fff',
              border: '1px solid #1a1a4e',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '13px',
            }}
          >
            Reset all data
          </button>
        </div>
      </header>

      {confirmingReset && (
        <div role="alertdialog" aria-label="Confirm reset" style={{
          padding: '12px 20px',
          background: '#3a1f2e',
          borderBottom: '1px solid #8b2f2c',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          fontSize: '13px',
        }}>
          <span>
            This permanently deletes all documents, indexed chunks, Q&amp;A history and feedback.
            {resetError && <span style={{ color: '#d9534f', marginLeft: '8px' }}>{resetError}</span>}
          </span>
          <div style={{ display: 'flex', gap: '8px', flexShrink: 0 }}>
            <button
              onClick={() => setConfirmingReset(false)}
              style={{
                padding: '5px 12px',
                background: '#0f3460',
                color: '#e0e0e0',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              Cancel
            </button>
            <button
              onClick={handleConfirmReset}
              style={{
                padding: '5px 12px',
                background: '#d9534f',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              Confirm reset
            </button>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: selected document (if any) above the question panel */}
        <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <div style={{
              maxHeight: '40%',
              overflow: 'auto',
              padding: '20px',
              borderBottom: '1px solid #0f3460',
              flexShrink: 0,
            }}>
              <DocumentDetail document={selectedDoc} />
            </div>
          )}
          <QuestionPanel
            history={history}
            onAsk={handleAskQuestion}
            onClearHistory={handleClearHistory}
          />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
