        <div role="alertdialog" aria-label="Confirm reset" style={{
          padding: '12px 20px',
          background: '#3a1f2e',
          borderBottom: '1px solid #8b2f2c',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          fontSize: '13px',
        }}>
          <span>
            This permanently deletes all documents, indexed chunks, Q&amp;A history and feedback.
            {resetError && <span style={{ color: '#d9534f', marginLeft: '8px' }}>{resetError}</span>}
          </span>
          <div style={{ display: 'flex', gap: '8px', flexShrink: 0 }}>
            <button
              onClick={() => setConfirmingReset(false)}
              style={{
                padding: '5px 12px',
                background: '#0f3460',
                color: '#e0e0e0',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              Cancel
            </button>
            <button
              onClick={handleConfirmReset}
              style={{
                padding: '5px 12px',
                background: '#d9534f',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              Confirm reset
            </button>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              onClick={handleImport}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: selected document (if any) above the question panel */}
        <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          {selectedDoc && (
            <div style={{
              maxHeight: '40%',
              overflow: 'auto',
              padding: '20px',
              borderBottom: '1px solid #0f3460',
              flexShrink: 0,
            }}>
              <DocumentDetail document={selectedDoc} />
            </div>
          )}
          <QuestionPanel
            history={history}
            onAsk={handleAskQuestion}
            onClearHistory={handleClearHistory}
          />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
EOF
