const { chromium } = require('playwright-core');

const PROJECT = '/Users/matiasrodriguezc/harness-runs/p06-haiku-weak';
const SAMPLE = `${PROJECT}/data/sample-documents/design-notes.md`;
const port = process.argv[2] || '9225';

let failures = 0;
function check(name, cond, detail = '') {
  console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${detail ? ' -- ' + detail : ''}`);
  if (!cond) failures++;
}

(async () => {
  const browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
  const page = browser.contexts()[0].pages()[0];
  await page.reload();
  await page.waitForLoadState('domcontentloaded');
  await page.waitForTimeout(800);

  // ---- Start from a known-empty state so the test is repeatable.
  await page.evaluate(() => window.knowledgeBase.app.reset());
  let docs = await page.evaluate(() => window.knowledgeBase.documents.list());
  check('reset empties documents', docs.length === 0, `count=${docs.length}`);
  let hist = await page.evaluate(() => window.knowledgeBase.qa.history());
  check('reset empties history', hist.length === 0);
  let fb = await page.evaluate(() => window.knowledgeBase.feedback.list());
  check('reset empties feedback', fb.length === 0);

  // ---- Import + index + ask through the preload API.
  const doc = await page.evaluate(p => window.knowledgeBase.documents.import(p), SAMPLE);
  check('import returns document', !!doc && !!doc.id);
  await page.evaluate(() => window.knowledgeBase.indexing.start());
  const status = await page.evaluate(() => window.knowledgeBase.indexing.status());
  check('indexing ready', status.indexStatus === 'ready', JSON.stringify(status));

  const r1 = await page.evaluate(() => window.knowledgeBase.qa.ask('What is the system architecture and design pattern?'));
  const r2 = await page.evaluate(() => window.knowledgeBase.qa.ask('How does logging and monitoring work?'));
  check('answer has string id', typeof r1.id === 'string' && r1.id.length > 0, r1.id);
  check('answer ids unique', r1.id !== r2.id);
  check('answer has citations', r1.citations.length > 0, `citations=${r1.citations.length}`);

  // ---- Feedback API.
  const sub = await page.evaluate(id => window.knowledgeBase.feedback.submit(id, 'up'), r1.id);
  check('submit returns entry', sub.answerId === r1.id && sub.rating === 'up' && !!sub.timestamp);
  await page.evaluate(id => window.knowledgeBase.feedback.submit(id, 'down'), r1.id);
  await page.evaluate(id => window.knowledgeBase.feedback.submit(id, 'up'), r2.id);
  fb = await page.evaluate(() => window.knowledgeBase.feedback.list());
  check('list has one entry per answer', fb.length === 2, JSON.stringify(fb.map(f => [f.answerId === r1.id ? 'r1' : 'r2', f.rating])));
  check('re-rating replaces previous rating',
    fb.find(f => f.answerId === r1.id)?.rating === 'down');
  check('list entry shape', Object.keys(fb[0]).sort().join(',') === 'answerId,rating,timestamp');

  const badRating = await page.evaluate(id => window.knowledgeBase.feedback.submit(id, 'meh').then(() => 'ok', e => 'rejected'), r1.id);
  check('invalid rating rejected', badRating === 'rejected');
  const badId = await page.evaluate(() => window.knowledgeBase.feedback.submit('no-such-id', 'up').then(() => 'ok', e => 'rejected'));
  check('unknown answer id rejected', badId === 'rejected');

  // ---- Conversation UI.
  await page.reload();
  await page.waitForTimeout(800);
  const helpfulBtns = await page.getByRole('button', { name: 'Mark answer helpful' }).count();
  const notHelpfulBtns = await page.getByRole('button', { name: 'Mark answer not helpful' }).count();
  check('two answers show helpful buttons', helpfulBtns === 2, `helpful=${helpfulBtns}`);
  check('two answers show not-helpful buttons', notHelpfulBtns === 2, `notHelpful=${notHelpfulBtns}`);

