const { chromium } = require('playwright-core');

const PROJECT = '/Users/matiasrodriguezc/harness-runs/p06-haiku-weak';
const SAMPLE = `${PROJECT}/data/sample-documents/retrieval-plan.md`;

// Usage:
//   node persist.js write <port>   -> import, index, ask, rate, then quit that app
//   node persist.js read <port>    -> check everything written earlier is still there
const [mode, port] = [process.argv[2], process.argv[3]];

(async () => {
  const browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
  const page = browser.contexts()[0].pages()[0];
  await page.reload();
  await page.waitForTimeout(800);

  if (mode === 'write') {
    await page.evaluate(() => window.knowledgeBase.app.reset());
    await page.evaluate(p => window.knowledgeBase.documents.import(p), SAMPLE);
    await page.evaluate(() => window.knowledgeBase.indexing.start());
    const a = await page.evaluate(() => window.knowledgeBase.qa.ask('How does retrieval rank chunks?'));
    await page.evaluate(id => window.knowledgeBase.feedback.submit(id, 'down'), a.id);
    console.log('wrote answer', a.id, 'rated down');
    // Quit this app instance; the next run starts a fresh process on the same data dir.
    await browser.close().catch(() => {});
    return;
  }

  const docs = await page.evaluate(() => window.knowledgeBase.documents.list());
  const hist = await page.evaluate(() => window.knowledgeBase.qa.history());
  const fb = await page.evaluate(() => window.knowledgeBase.feedback.list());
  const status = await page.evaluate(() => window.knowledgeBase.indexing.status());
  console.log('documents:', docs.length, '| history:', hist.length, '| feedback:', JSON.stringify(fb));
  console.log('index status:', status.status, status.currentIndexed + '/' + status.totalDocuments);
  const pressed = await page.getByRole('button', { name: 'Mark answer not helpful' }).first().getAttribute('aria-pressed').catch(() => 'n/a');
  console.log('UI shows "not helpful" pressed after restart:', pressed);
  const ok = docs.length === 1 && hist.length === 1 && fb.length === 1 && fb[0].rating === 'down' && pressed === 'true';
  console.log(ok ? 'RESTART PERSISTENCE: PASS' : 'RESTART PERSISTENCE: FAIL');
  await browser.close();
  process.exit(ok ? 0 : 1);
})().catch(e => {
  console.error('ERR', e.stack || e.message);
  process.exit(2);
});

